; ---------------------------------------------------------------------------
; Internal ROM header ($00:FFB0-$00:FFFF)
; The title is 22 characters long and overflows into $FFD5 (normally the
; map mode byte); it is reproduced exactly as in the original ROM.
; ---------------------------------------------------------------------------
rom_header:
	.byte	$16, $6B, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF	; maker code, game code, reserved, expansion
	.byte	"CONTRA3 THE ALIEN WARS"	; title (22 chars, $FFC0-$FFD5)
	.byte	$00	; $FFD6 cartridge type
	.byte	$0A	; $FFD7 ROM size
	.byte	$00	; $FFD8 SRAM size
	.byte	$01	; $FFD9 region
	.byte	$A4	; $FFDA developer ID
	.byte	$00	; $FFDB version
	.word	$F3C3	; $FFDC checksum complement
	.word	$0C3C	; $FFDE checksum
vectors:
	.word	$FFFF	; native: reserved
	.word	$FFFF	; native: reserved
	.addr	irq	; native COP
	.addr	irq	; native BRK
	.addr	irq	; native ABORT
	.addr	nmi	; native NMI
	.addr	reset	; native (unused)
	.addr	irq	; native IRQ
	.word	$FFFF	; emulation: reserved
	.word	$FFFF	; emulation: reserved
	.addr	irq	; emulation COP
	.addr	irq	; emulation (unused)
	.addr	irq	; emulation ABORT
	.addr	nmi	; emulation NMI
	.addr	reset	; emulation RESET
	.addr	irq	; emulation IRQ/BRK
